export const mathematicsConceptPath = (concept: Pick<MathematicalConcept, 'slug'>) => `${MATHEMATICS_KNOWLEDGE_PATH}/${concept.slug}`
export const getMathematicalConcept = (slug: string) => MATHEMATICAL_CONCEPTS.find((concept) => concept.slug === slug)
export const getConceptBridges = (conceptId: string) => MATHEMATICAL_BRIDGES.filter((bridge) => bridge.conceptId === conceptId)
export const getDomainBridges = (domain: MathematicsDomain) => MATHEMATICAL_BRIDGES.filter((bridge) => bridge.domain === domain)

export const MATHEMATICS_KNOWLEDGE_REGISTRY = {
  version: MATHEMATICS_KNOWLEDGE_VERSION,
  releasedOn: MATHEMATICS_KNOWLEDGE_RELEASE_DATE,
  schemaPurpose: 'A connective mathematical grammar for calculations, models, formalized traditions, and empirical tests. It does not transfer scientific validity between domains.',
  concepts: MATHEMATICAL_CONCEPTS,
  bridges: MATHEMATICAL_BRIDGES,
  sources: MATHEMATICS_SOURCES,
} as const

function assertMathematicsRegistry() {
  // A floor, not an exact count. The guard exists to catch concepts being
  // dropped by accident, which a floor does; pinning the exact number also
  // blocks the corpus from growing, and the bridge check below already uses a
  // range for the same reason.
  if (MATHEMATICAL_CONCEPTS.length < 24) throw new Error(`Expected at least 24 mathematical concepts, received ${MATHEMATICAL_CONCEPTS.length}`)
  if (MATHEMATICAL_BRIDGES.length < 40 || MATHEMATICAL_BRIDGES.length > 45) throw new Error(`Expected approximately 40 bridges, received ${MATHEMATICAL_BRIDGES.length}`)
  const conceptIds = new Set(MATHEMATICAL_CONCEPTS.map((concept) => concept.id))
  const sourceIds = new Set(MATHEMATICS_SOURCES.map((source) => source.id))
  if (conceptIds.size !== MATHEMATICAL_CONCEPTS.length) throw new Error('Duplicate mathematical concept ID')
  if (new Set(MATHEMATICAL_BRIDGES.map((bridge) => bridge.id)).size !== MATHEMATICAL_BRIDGES.length) throw new Error('Duplicate mathematical bridge ID')
  for (const concept of MATHEMATICAL_CONCEPTS) {
    if (!concept.sourceIds.every((id) => sourceIds.has(id))) throw new Error(`${concept.id} references an unknown source`)
    if (!concept.relatedSlugs.every((slug) => MATHEMATICAL_CONCEPTS.some((candidate) => candidate.slug === slug))) throw new Error(`${concept.id} references an unknown concept`)
  }
  for (const bridge of MATHEMATICAL_BRIDGES) if (!conceptIds.has(bridge.conceptId)) throw new Error(`${bridge.id} references an unknown concept`)
  for (const category of MATHEMATICS_CATEGORIES) if (!MATHEMATICAL_CONCEPTS.some((concept) => concept.category === category)) throw new Error(`${category} has no concepts`)
  for (const domain of MATHEMATICS_DOMAINS) if (getDomainBridges(domain).length < 6) throw new Error(`${domain} has too few bridges`)
}

assertMathematicsRegistry()

export const MATHEMATICS_REGISTRY_URL = `${SITE_URL}${MATHEMATICS_REGISTRY_PATH}`
